import { CurrencyAmount, Percent, TradeType, } from '@uniswap/sdk-core';
import { Pool, Route, SwapQuoter, Trade, } from '@uniswap/v3-sdk';
import { ethers } from 'ethers';
import { CurrentConfig } from './config.js';
import { ERC20_ABI, QUOTER_CONTRACT_ADDRESS, SWAP_ROUTER_ADDRESS, TOKEN_AMOUNT_TO_APPROVE_FOR_TRANSFER, } from './constants.js';
import { MAX_FEE_PER_GAS, MAX_PRIORITY_FEE_PER_GAS } from './constants.js';
import { getPoolInfo } from './pool.js';
import { getWalletAddress, sendTransaction, TransactionState, getMainnetProvider, } from './providers.js';
import { fromReadableAmount } from './utils.js';
// Trading Functions
// CREATE TRADE
export async function createTrade() {
    console.log('Creating trade');
    const poolInfo = await getPoolInfo(); // ✅
    const pool = new Pool(CurrentConfig.tokens.in, CurrentConfig.tokens.out, CurrentConfig.tokens.poolFee, poolInfo.sqrtPriceX96.toString(), poolInfo.liquidity.toString(), poolInfo.tick);
    console.error('pool', JSON.stringify(pool, null, 2));
    const swapRoute = new Route([pool], CurrentConfig.tokens.in, CurrentConfig.tokens.out);
    const amountOut = await getOutputQuote(swapRoute); // ✅
    const uncheckedTrade = Trade.createUncheckedTrade({
        route: swapRoute,
        inputAmount: CurrencyAmount.fromRawAmount(CurrentConfig.tokens.in, fromReadableAmount(CurrentConfig.tokens.amountIn, CurrentConfig.tokens.in.decimals).toString()),
        outputAmount: CurrencyAmount.fromRawAmount(CurrentConfig.tokens.out, amountOut[0].toString()),
        tradeType: TradeType.EXACT_INPUT,
    });
    return uncheckedTrade;
}
// EXECUTE TRADE
export async function executeTrade(trade) {
    console.log('executing trade');
    const walletAddress = getWalletAddress(); // Need to pass down the agent wallet
    console.log('walletAddress', walletAddress);
    const provider = getMainnetProvider(); // ✅
    console.log('provider', provider);
    if (!walletAddress || !provider) {
        throw new Error('Cannot execute a trade without a connected wallet');
    }
    // Give approval to the router to spend the token
    console.log('attempting to approve token');
    // Need to make this a userOp txn for the approval
    const tokenApproval = await getTokenTransferApproval(CurrentConfig.tokens.in);
    console.log('tokenApproval', tokenApproval);
    // Fail if transfer approvals do not go through
    // * Does this still work if done through userOp?
    if (tokenApproval !== TransactionState.Sent) {
        console.log('tokenApproval failed');
        return TransactionState.Failed;
    }
    console.log('attempting to swap');
    // Create parameters for SwapRouter02's exactInputSingle function directly
    // Looks like quotient might rely on JSBI, so we need to convert the amountIn and amountOutMinimum to JSBI
    const params = {
        tokenIn: CurrentConfig.tokens.in.address,
        tokenOut: CurrentConfig.tokens.out.address,
        fee: CurrentConfig.tokens.poolFee,
        recipient: walletAddress,
        amountIn: trade.inputAmount.quotient.toString(),
        amountOutMinimum: trade.minimumAmountOut(new Percent(500, 10_000)).quotient.toString(), // 5% slippage
        sqrtPriceLimitX96: 0,
    };
    // Create the interface for SwapRouter02
    const swapRouterInterface = new ethers.utils.Interface([
        'function exactInputSingle((address tokenIn, address tokenOut, uint24 fee, address recipient, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountOut)'
    ]);
    // Encode the function call
    // this is probably the call data we can pass into the userOp prepareCalls
    const calldata = swapRouterInterface.encodeFunctionData('exactInputSingle', [params]);
    // where would we add the params for this? I think everything but the value, data, and to address can be removesd
    const tx = {
        data: calldata,
        to: SWAP_ROUTER_ADDRESS,
        value: '0x0', // No ETH being sent
        from: walletAddress,
        maxFeePerGas: MAX_FEE_PER_GAS,
        maxPriorityFeePerGas: MAX_PRIORITY_FEE_PER_GAS,
        gasLimit: ethers.BigNumber.from(500000),
        type: 2,
        chainId: 11155111, // Sepolia chainId
    };
    console.log('sending transaction');
    // sendPrepared calls
    const res = await sendTransaction(tx);
    console.log('transaction response', res);
    return res;
}
// Helper Quoting and Pool Functions
async function getOutputQuote(route) {
    const provider = getMainnetProvider();
    if (!provider) {
        throw new Error('Provider required to get pool state');
    }
    const { calldata } = await SwapQuoter.quoteCallParameters(route, CurrencyAmount.fromRawAmount(CurrentConfig.tokens.in, fromReadableAmount(CurrentConfig.tokens.amountIn, CurrentConfig.tokens.in.decimals).toString()), TradeType.EXACT_INPUT, {
        useQuoterV2: true,
    });
    const quoteCallReturnData = await provider.call({
        to: QUOTER_CONTRACT_ADDRESS,
        data: calldata,
    });
    return ethers.utils.defaultAbiCoder.decode(['uint256'], quoteCallReturnData);
}
export async function getTokenTransferApproval(token) {
    console.log('getting token transfer approval');
    const provider = getMainnetProvider();
    const address = getWalletAddress();
    if (!provider || !address) {
        console.log('No Provider Found');
        return TransactionState.Failed;
    }
    try {
        const tokenContract = new ethers.Contract(token.address, ERC20_ABI, provider);
        console.log('attempting to approve token');
        const transaction = await tokenContract.populateTransaction.approve(SWAP_ROUTER_ADDRESS, fromReadableAmount(TOKEN_AMOUNT_TO_APPROVE_FOR_TRANSFER, token.decimals).toString());
        console.log('transaction', transaction);
        const res = await sendTransaction({
            ...transaction,
            from: address,
        });
        console.log('res', res);
        return res;
    }
    catch (e) {
        console.error('token transfer approval failed', e);
        return TransactionState.Failed;
    }
}
